/* ---------- Activity editors: Quiz, True/False, Fill the gaps, Assignment ---------- */
function actAfterInput(k,v){const a=ACTS[k[1]];if(!a)return;
 if(k[2]==='name'&&a.type==='assignment'){a.title=(a.title.startsWith('Essay:')?'Essay: ':'Assignment: ')+v;document.querySelectorAll(`[data-show="act.${a.id}.title"]`).forEach(n=>n.textContent=a.title);}}
const LEARNER_ASG={uxplan:'a1',uxscript:'a2',figtest:'a3'};
VIEWS['admin:activity']=(r)=>{const a=ACTS[r.id];if(!a||a.deleted)return VIEWS['admin:library']();
 const l=a.lesson?lessonById(a.lesson):null,c=a.course,mods=crsMods(c);
 const crumbs=['<a class="crumb" href="#/admin/courses">Courses</a>',`<button class="crumb" data-act="cedopen" data-c="${c}" data-tab="curriculum">${esc(CED[c].title)}</button>`].concat(l?[esc(`Module ${l.mod+1} · ${mods[l.mod]}`),`<a class="crumb" href="#/admin/lesson/${l.id}">${esc(l.title)}</a>`]:['<a class="crumb" href="#/admin/library">Library</a>']).join(' / ');
 const back=l?`data-act="nav" data-to="admin/lesson/${l.id}"`:'data-act="nav" data-to="admin/library"';
 const head=edHead({backAttrs:back,crumbs,title:a.title,empty:'Untitled '+ACT_TYPE[a.type].toLowerCase(),bind:`act.${a.id}.title`,status:a.status,preview:`data-act="actpreview" data-a="${a.id}"`,primary:`data-act="actupdate" data-a="${a.id}"`,kind:'activity',id:a.id});
 const body={quiz:quizEd,tf:tfEd,gaps:gapsEd,assignment:asgEd}[a.type](a);
 const title=a.type!=='assignment'&&(a.isNew||!a.title)?`<section class="card pad">${fld('Title',eIn(`act.${a.id}.title`,a.title,{ph:{quiz:'For example: Quiz: Funnel metrics',tf:'For example: True/False: Interview do and don’t',gaps:'For example: Fill the gaps: Name the research method'}[a.type]}))}</section>`:'';
 return head+`<div class="page" style="max-width:none;padding-top:24px">${title}${body}</div>`;};
function actProblem(a){if(!a.title.trim()||(a.type==='assignment'&&!(a.name||'').trim()))return {msg:'Add a title first'};
 if(a.type==='quiz'){const i=a.questions.findIndex(q=>!q.text.trim());if(i>=0)return {sel:i,msg:`Question ${i+1} has no text yet`};const k=a.questions.findIndex(q=>!q.answers.some(x=>x.ok));if(k>=0)return {sel:k,msg:`Mark the correct answer in question ${k+1} first`};const e=a.questions.findIndex(q=>q.answers.some(x=>!x.t.trim()));if(e>=0)return {sel:e,msg:`Question ${e+1} has an empty answer`};}
 if(a.type==='tf'){const i=a.statements.findIndex(s=>!s.text.trim());if(i>=0)return {sel:i,msg:`Statement ${i+1} is empty`};}
 if(a.type==='gaps'){const i=a.sentences.findIndex(s=>!s.gap);if(i>=0)return {sel:i,msg:`Sentence ${i+1} has no gap yet`};}
 if(a.type==='assignment'){if(!a.instr.trim())return {msg:'Add instructions first'};if(!a.due.trim())return {msg:'Set a due date first'};}
 return null;}
ACT.actupdate=(el)=>{const a=ACTS[el.dataset.a];const p=actProblem(a);if(p){if(p.sel!=null){a.sel=p.sel;if(a.type==='tf'&&p.sel>3)a.showAll=true;}render();toast(p.msg);return;}
 if(a.status==='published'){toast(a.type==='assignment'&&a.stats?`Changes are live · ${a.stats.submitted} learners who already submitted keep their version`:'Changes are live for learners');return;}
 if(a.lesson&&lessonById(a.lesson).course==='sd'){toast('Publish the course first: it is still a draft');return;}
 a.status='published';a.isNew=false;render();toast('Published · learners see it after the lesson');};
ACT.actpreview=(el)=>{const id=el.dataset.a;if(LEARNER_ASG[id]){go('learner/assignment/'+LEARNER_ASG[id]);setTimeout(()=>toast('You are previewing the assignment as a learner','Back to editor',()=>go('admin/activity/'+id)),60);return;}
 toast(ACTS[id].type==='assignment'?'Learners see it after you publish':'The learner view of quizzes and exercises opens inside the lesson player, which is not part of this prototype');};
ACT.actdel=(el)=>{st.menu=null;const a=ACTS[el.dataset.id];a.deleted=true;go(a.lesson?'admin/lesson/'+a.lesson:'admin/library');setTimeout(()=>toast(`“${a.title||'Untitled'}” deleted`,'Undo',()=>{a.deleted=false;render();}),40);};

/* Quiz */
function quizEd(a){const qi=Math.min(a.sel||0,a.questions.length-1),q=a.questions[qi];
 const meta=x=>{const n=x.answers.filter(y=>y.ok).length;return n?`${n} correct · ${x.answers.length} answers`:null;};
 return `<div class="row gap20" style="align-items:flex-start">
  <section class="card qlist" style="overflow:hidden"><div class="row between" style="padding:14px 16px"><h3 class="h3">Questions · ${a.questions.length}</h3><button class="link" data-act="qadd" data-a="${a.id}">Add question</button></div>
   ${a.questions.map((x,i)=>`<button class="qitem ${i===qi?'on':''}" data-act="qsel" data-a="${a.id}" data-i="${i}"><span class="grip" style="padding-top:4px">${ic('grip',14)}</span><span class="numtile ${i===qi?'on':''}" style="width:24px;height:24px">${i+1}</span><span class="col gap2 grow" style="min-width:0"><span class="s med" data-show="act.${a.id}.questions.${i}.text" data-empty="New question">${esc(x.text||'New question')}</span>${meta(x)?`<span class="c faded">${meta(x)}</span>`:`<span class="c amber row gap4">${ic('alert',12)}No correct answer marked</span>`}</span></button>`).join('')}</section>
  <div class="col gap20 grow" style="min-width:0">
   <section class="card pad24 col gap16"><div class="row between gap12"><h3 class="h3">Question ${qi+1} of ${a.questions.length}</h3><div class="row gap8"><span class="c faded">Answer type</span><div class="seg light auto">${[['one','One correct'],['many','Several correct']].map(([v,l])=>`<button class="${q.type===v?'on':''}" data-act="qtype" data-a="${a.id}" data-v="${v}">${l}</button>`).join('')}</div></div></div>
    ${fld('Question',eArea(`act.${a.id}.questions.${qi}.text`,q.text,{ph:'Type the question learners will see',h:56}))}
    <div class="field"><div class="row between"><span class="label">Answers</span><span class="c faded">${q.type==='many'?'Mark every correct one':'Mark the correct one'}</span></div>
     ${q.answers.map((x,j)=>`<div class="ans ${x.ok?'ok':''}"><button class="radio ${q.type==='many'?'sq':''} ${x.ok?'on':''}" data-act="qok" data-a="${a.id}" data-j="${j}" aria-label="Mark answer ${j+1} as correct">${q.type==='many'&&x.ok?ic('check',12):''}</button><input data-ed="act.${a.id}.questions.${qi}.answers.${j}.t" value="${esc(x.t)}" placeholder="Answer ${j+1}">${x.ok?`<span class="c green row gap4" style="white-space:nowrap">${ic('check',12)}Correct answer</span>`:''}<button class="faded" data-act="qdelans" data-a="${a.id}" data-j="${j}" aria-label="Delete answer ${j+1}">${ic('trash',16)}</button></div>`).join('')}
     <span><button class="link" data-act="qaddans" data-a="${a.id}">${ic('plus',14)}Add answer</button></span></div>
    ${q.answers.some(x=>x.ok)?'':`<div class="alert row gap8" style="background:var(--highlighter-wash);padding:10px 12px;align-items:center">${ic('alert',16,'amber')}<span class="s">Mark the correct answer: without it learners can’t pass this question and the quiz can’t be updated.</span></div>`}
    ${fld('Explanation · shown after answering',eArea(`act.${a.id}.questions.${qi}.expl`,q.expl,{ph:'Why this answer is correct',h:56}))}
   </section>
   <section class="card pad24 col gap16"><h3 class="h3">Quiz settings</h3><div class="row gap12">${fld('Passing score',eSel(`act.${a.id}.settings.pass`,a.settings.pass,['50%','60%','70%','80%','90%']))}${fld('Attempts',eSel(`act.${a.id}.settings.attempts`,a.settings.attempts,['1','2','3','Unlimited']))}${fld('Show correct answers',eSel(`act.${a.id}.settings.show`,a.settings.show,['Right away','After the due date','Never']))}</div>${eTog(`act.${a.id}.settings.shuffle`,a.settings.shuffle,'Shuffle answers for each learner')}</section>
  </div></div>`;}
const curQ=a=>a.questions[Math.min(a.sel||0,a.questions.length-1)];
ACT.qsel=(el)=>{ACTS[el.dataset.a].sel=+el.dataset.i;render();};
ACT.qtype=(el)=>{const a=ACTS[el.dataset.a],q=curQ(a),v=el.dataset.v;if(v==='one'){let seen=false;q.answers.forEach(x=>{if(x.ok){if(seen)x.ok=false;seen=true;}});}q.type=v;edSaving();render();};
ACT.qok=(el)=>{const a=ACTS[el.dataset.a],q=curQ(a),j=+el.dataset.j;if(q.type==='many')q.answers[j].ok=!q.answers[j].ok;else q.answers.forEach((x,k)=>{x.ok=k===j;});edSaving();render();};
ACT.qaddans=(el)=>{const q=curQ(ACTS[el.dataset.a]);q.answers.push({t:'',ok:false});edSaving();render();const ins=document.querySelectorAll('.ans input');if(ins.length)ins[ins.length-1].focus();};
ACT.qdelans=(el)=>{const q=curQ(ACTS[el.dataset.a]),j=+el.dataset.j;if(q.answers.length<=2){toast('A question needs at least 2 answers');return;}const [x]=q.answers.splice(j,1);edSaving();render();toast('Answer deleted','Undo',()=>{q.answers.splice(j,0,x);render();});};
ACT.qadd=(el)=>{const a=ACTS[el.dataset.a];a.questions.push({text:'',type:'one',answers:[{t:'',ok:false},{t:'',ok:false}],expl:''});a.sel=a.questions.length-1;edSaving();render();const t=document.querySelector(`[data-ed="act.${a.id}.questions.${a.sel}.text"]`);if(t)t.focus();};

/* True / False */
function tfEd(a){const n=a.statements.length,si=Math.min(a.sel||0,n-1),sel=a.statements[si];const shown=a.showAll||n<=4?a.statements:a.statements.slice(0,4);
 return `<div class="ed-cols"><section class="card grow" style="overflow:hidden;min-width:0"><div class="row between" style="padding:14px 16px"><h3 class="h3">Statements · ${n}</h3><span class="c faded">Learners mark each one as true or false</span></div>
  ${shown.map((s,i)=>`<div class="stmt ${i===si?'on':''}" data-act="tfsel" data-a="${a.id}" data-i="${i}"><div class="row gap10"><span class="grip">${ic('grip',14)}</span><span class="c faded" style="width:14px">${i+1}</span><label class="input grow" style="height:38px"><input data-ed="act.${a.id}.statements.${i}.text" value="${esc(s.text)}" placeholder="Type a statement"></label><span class="col gap2"><span class="c faded">Correct answer</span><div class="seg light auto">${[['true','True'],['false','False']].map(([v,l])=>`<button class="${String(s.ans)===v?'on':''}" data-act="tfans" data-a="${a.id}" data-i="${i}" data-v="${v}">${l}</button>`).join('')}</div></span><button class="faded" data-act="tfmore" data-a="${a.id}" data-i="${i}" aria-label="More for statement ${i+1}">${ic('more',16)}</button></div>
   ${i===si?`<div class="row gap8" style="padding-left:46px"><span class="c faded" style="white-space:nowrap">Explanation:</span><label class="input grow" style="height:34px"><input data-ed="act.${a.id}.statements.${i}.expl" value="${esc(s.expl)}" placeholder="Why it is true or false"></label></div>`:`<span class="c faded" style="padding-left:46px">Explanation: <span class="pencil">${esc(s.expl||'—')}</span></span>`}</div>`).join('')}
  <div class="row between" style="padding:12px 16px;border-top:1px solid var(--rule)">${n>4?`<button class="link" style="color:var(--pencil)" data-act="tfall" data-a="${a.id}">${a.showAll?'Show fewer':`Show ${n-4} more statement${n-4>1?'s':''}`}</button>`:'<span></span>'}<button class="link" data-act="tfadd" data-a="${a.id}">${ic('plus',14)}Add statement</button></div></section>
 <div class="ed-side"><section class="card pad col gap12"><div class="row gap8 s pencil">${ic('eye',16)}What learners see</div><span class="c faded">Statement ${si+1} of ${n}</span><span class="m med" data-show="act.${a.id}.statements.${si}.text" data-empty="Type a statement">${esc(sel.text||'Type a statement')}</span><div class="row gap8"><span class="btn btn-secondary grow">True</span><span class="btn btn-secondary grow">False</span></div></section>
  <section class="card pad col gap12"><h3 class="h3">Settings</h3>${fld('Passing score',eSel(`act.${a.id}.settings.pass`,a.settings.pass,Array.from({length:n},(_,k)=>`${k+1} of ${n}`)))}${eTog(`act.${a.id}.settings.shuffle`,a.settings.shuffle,'Shuffle statements')}</section></div></div>`;}
ACT.tfsel=(el,e)=>{const a=ACTS[el.dataset.a],i=+el.dataset.i;if(a.sel===i)return;a.sel=i;const inInput=e&&e.target&&e.target.tagName==='INPUT';render();if(inInput){const t=document.querySelector(`[data-ed="act.${a.id}.statements.${i}.text"]`);if(t){t.focus();t.setSelectionRange(t.value.length,t.value.length);}}};
ACT.tfans=(el)=>{const a=ACTS[el.dataset.a],i=+el.dataset.i;a.statements[i].ans=el.dataset.v==='true';a.sel=i;edSaving();render();};
ACT.tfall=(el)=>{const a=ACTS[el.dataset.a];a.showAll=!a.showAll;if(!a.showAll&&a.sel>3)a.sel=0;render();};
ACT.tfadd=(el)=>{const a=ACTS[el.dataset.a];a.statements.push({text:'',ans:true,expl:''});a.sel=a.statements.length-1;a.showAll=true;const n=a.statements.length;a.settings.pass=`${Math.max(1,Math.round(n*0.75))} of ${n}`;edSaving();render();const t=document.querySelector(`[data-ed="act.${a.id}.statements.${a.sel}.text"]`);if(t)t.focus();};
ACT.tfmore=(el)=>openMenu(el,`<button class="mi" data-act="tfdel" data-a="${el.dataset.a}" data-i="${el.dataset.i}">${ic('trash',14)}Delete statement</button>`,'tfmore',{w:200});
ACT.tfdel=(el)=>{st.menu=null;const a=ACTS[el.dataset.a],i=+el.dataset.i;if(a.statements.length<=1){renderLayer();toast('Keep at least 1 statement');return;}const [x]=a.statements.splice(i,1);a.sel=Math.max(0,i-1);edSaving();render();toast(`Statement ${i+1} deleted`,'Undo',()=>{a.statements.splice(i,0,x);a.sel=i;render();});};

/* Fill the gaps */
const PUNCT=/^[.,!?;:]+$/;
function gTokens(text){const out=[];String(text).split(/\s+/).filter(Boolean).forEach(w=>{const m=w.match(/^(.*?)([.,!?;:]+)$/);if(m&&m[1]){out.push(m[1]);out.push(m[2]);}else out.push(w);});return out;}
function gRange(toks,gap){if(!gap)return null;const g=gTokens(gap);for(let i=0;i<=toks.length-g.length;i++){if(g.every((w,k)=>toks[i+k]===w))return [i,i+g.length-1];}return null;}
const gJoin=toks=>toks.reduce((h,t,k)=>h+(k&&!PUNCT.test(t)?' ':'')+esc(t),'');
function gView(s,mode){const toks=gTokens(s.text),R=gRange(toks,s.gap);if(!R)return gJoin(toks);const after=toks.slice(R[1]+1);
 return gJoin(toks.slice(0,R[0]))+(R[0]?' ':'')+(mode==='blank'?'<span class="blank"></span>':`<span class="wd gap">${gJoin(toks.slice(R[0],R[1]+1))}</span>`)+(after.length&&!PUNCT.test(after[0])?' ':'')+gJoin(after);}
/* the gap is 1 chip even when it is 2 words; punctuation sits right after its word, as in the mockup */
function gEdit(a,s,i){const toks=gTokens(s.text),R=gRange(toks,s.gap),G=st.gsel&&st.gsel.a===a.id&&st.gsel.s===i?st.gsel:null;
 return toks.map((t,k)=>{const p=PUNCT.test(t);const sel=G&&k>=G.from&&k<=G.to;const w=p?esc(t):`<span class="wd ${sel?'sel':''}" data-act="gword" data-a="${a.id}" data-s="${i}" data-t="${k}">${esc(t)}</span>`;
  return (k&&!p?' ':'')+(R&&k===R[0]?'<span class="gapchip">':'')+w+(R&&k===R[1]?'</span>':'');}).join('');}
function gapsEd(a){const si=Math.min(a.sel||0,a.sentences.length-1);
 const editRow=(s,i)=>{if(s.edit||!s.text.trim())return `<div class="stmt on"><div class="row gap10"><span class="grip">${ic('grip',14)}</span><span class="c faded">${i+1}</span><label class="input grow"><input data-ed="act.${a.id}.sentences.${i}.text" value="${esc(s.text)}" placeholder="Type a sentence, for example: Use card sorting to see how people group menu items."></label>${btn('Done','secondary btn-sm',`data-act="gdone" data-a="${a.id}" data-i="${i}"`)}</div><span class="c faded" style="padding-left:46px">Then select the word learners should type and make it a gap.</span></div>`;
  const has=st.gsel&&st.gsel.a===a.id&&st.gsel.s===i;
  return `<div class="stmt on"><div class="row gap10" style="align-items:flex-start"><span class="grip" style="padding-top:6px">${ic('grip',14)}</span><span class="c faded" style="padding-top:6px">${i+1}</span><div class="col gap10 grow" style="min-width:0"><div class="row gap8">${btn('Make a gap','primary btn-sm',`data-act="gmake" data-a="${a.id}" data-i="${i}" ${has?'':'disabled'}`)}${s.gap?btn('Remove gap','ghost btn-sm',`data-act="gremove" data-a="${a.id}" data-i="${i}"`):''}<button class="link" style="margin-left:auto;color:var(--pencil)" data-act="gedit" data-a="${a.id}" data-i="${i}">Edit text</button></div>
   <div class="m" style="border:1px solid var(--ink-violet);box-shadow:0 0 0 1px var(--ink-violet);border-radius:8px;padding:6px 10px;background:var(--sheet);line-height:28px">${gEdit(a,s,i)}</div>
   ${s.gap?`<div class="row gap6" style="flex-wrap:wrap"><span class="c faded">Accepted answers:</span>${s.acc.map((x,k)=>`<span class="acc">${esc(x)}<button class="faded" data-act="gaccdel" data-a="${a.id}" data-i="${i}" data-k="${k}" aria-label="Remove ${esc(x)}">${ic('x',12)}</button></span>`).join('')}${st.gaccAdd===a.id+':'+i?`<label class="input" style="height:28px;width:170px"><input data-gacc="${a.id}:${i}" placeholder="Another answer · Enter"></label>`:`<button class="link" data-act="gaccadd" data-a="${a.id}" data-i="${i}">${ic('plus',12)}Add answer</button>`}</div>`:'<span class="c amber">Click a word (or 2 words next to each other), then “Make a gap”.</span>'}</div><button class="faded" data-act="gmore" data-a="${a.id}" data-i="${i}" aria-label="More for sentence ${i+1}">${ic('more',16)}</button></div></div>`;};
 const viewRow=(s,i)=>`<div class="stmt" data-act="gsel" data-a="${a.id}" data-i="${i}" style="cursor:pointer"><div class="row gap10" style="align-items:flex-start"><span class="grip" style="padding-top:4px">${ic('grip',14)}</span><span class="c faded" style="padding-top:4px">${i+1}</span><div class="col gap4 grow" style="min-width:0"><span class="m" style="line-height:26px">${gView(s)}</span><span class="c faded">${s.gap?'Accepted: '+s.acc.map(esc).join(', '):'No gap yet'}</span></div><button class="faded" data-act="gmore" data-a="${a.id}" data-i="${i}" aria-label="More for sentence ${i+1}">${ic('more',16)}</button></div></div>`;
 return `<div class="ed-cols"><section class="card grow" style="overflow:hidden;min-width:0"><div class="row between" style="padding:14px 16px"><h3 class="h3">Sentences · ${a.sentences.length}</h3><span class="c faded">Select a word, then “Make a gap”</span></div>
  ${a.sentences.map((s,i)=>i===si?editRow(s,i):viewRow(s,i)).join('')}
  <div style="padding:12px 16px;border-top:1px solid var(--rule)"><button class="link" data-act="gadd" data-a="${a.id}">${ic('plus',14)}Add sentence</button></div></section>
 <div class="ed-side"><section class="card pad col gap12"><div class="row gap8 s pencil">${ic('eye',16)}What learners see</div>${a.sentences.filter(s=>s.text.trim()&&!s.edit&&s.gap).map(s=>`<p class="m" style="margin:0;line-height:30px">${gView(s,'blank')}</p>`).join('')||'<span class="s faded">Sentences show here once they have a gap.</span>'}</section>
  ${sideNote('Learners type the missing words. Every accepted answer counts as correct; capital letters don’t matter.')}</div></div>`;}
ACT.gsel=(el)=>{const a=ACTS[el.dataset.a];a.sel=+el.dataset.i;st.gsel=null;st.gaccAdd=null;render();};
ACT.gword=(el)=>{const id=el.dataset.a,s=+el.dataset.s,k=+el.dataset.t;const G=st.gsel;
 if(G&&G.a===id&&G.s===s&&(k<G.from||k>G.to)&&Math.min(Math.abs(k-G.from),Math.abs(k-G.to))<=3)st.gsel={a:id,s,from:Math.min(G.from,k),to:Math.max(G.to,k)};
 else if(G&&G.a===id&&G.s===s&&G.from===k&&G.to===k)st.gsel=null;else st.gsel={a:id,s,from:k,to:k};render();};
ACT.gmake=(el)=>{const a=ACTS[el.dataset.a],i=+el.dataset.i,G=st.gsel;if(!G)return;const s=a.sentences[i];const toks=gTokens(s.text).slice(G.from,G.to+1).filter(t=>!PUNCT.test(t));const gap=toks.join(' ');s.gap=gap;s.acc=[gap.toLowerCase()];st.gsel=null;edSaving();render();};
ACT.gremove=(el)=>{const s=ACTS[el.dataset.a].sentences[+el.dataset.i];s.gap=null;s.acc=[];edSaving();render();};
ACT.gedit=(el)=>{const s=ACTS[el.dataset.a].sentences[+el.dataset.i];s.edit=true;st.gsel=null;render();};
ACT.gdone=(el)=>{const a=ACTS[el.dataset.a],s=a.sentences[+el.dataset.i];if(!s.text.trim()){toast('Type a sentence first');return;}s.edit=false;if(s.gap&&!gRange(gTokens(s.text),s.gap)){s.gap=null;s.acc=[];}edSaving();render();};
ACT.gaccadd=(el)=>{st.gaccAdd=el.dataset.a+':'+el.dataset.i;render();const t=document.querySelector('[data-gacc]');if(t)t.focus();};
ACT.gaccdel=(el)=>{const s=ACTS[el.dataset.a].sentences[+el.dataset.i];if(s.acc.length<=1){toast('Keep at least 1 accepted answer');return;}s.acc.splice(+el.dataset.k,1);edSaving();render();};
document.addEventListener('keydown',e=>{const t=e.target;if(!t.dataset||!t.dataset.gacc)return;if(e.key==='Enter'){e.preventDefault();const [id,i]=t.dataset.gacc.split(':');const v=t.value.trim();if(v){ACTS[id].sentences[+i].acc.push(v);edSaving();}st.gaccAdd=null;render();}else if(e.key==='Escape'){st.gaccAdd=null;render();}});
ACT.gadd=(el)=>{const a=ACTS[el.dataset.a];a.sentences.push({text:'',gap:null,acc:[],edit:true});a.sel=a.sentences.length-1;st.gsel=null;edSaving();render();const t=document.querySelector(`[data-ed="act.${a.id}.sentences.${a.sel}.text"]`);if(t)t.focus();};
ACT.gmore=(el)=>openMenu(el,`<button class="mi" data-act="gdel" data-a="${el.dataset.a}" data-i="${el.dataset.i}">${ic('trash',14)}Delete sentence</button>`,'gmore',{w:200});
ACT.gdel=(el)=>{st.menu=null;const a=ACTS[el.dataset.a],i=+el.dataset.i;if(a.sentences.length<=1){renderLayer();toast('Keep at least 1 sentence');return;}const [x]=a.sentences.splice(i,1);a.sel=Math.max(0,Math.min(a.sel,a.sentences.length-1));st.gsel=null;edSaving();render();toast(`Sentence ${i+1} deleted`,'Undo',()=>{a.sentences.splice(i,0,x);a.sel=i;render();});};

/* Assignment */
function asgEd(a){const S=a.stats;
 return `<div class="ed-cols"><div class="col gap20 grow" style="min-width:0">
  ${section(1,'Task','1 place for instructions. Learners see it as “What to submit”.',`${fld('Title',eIn(`act.${a.id}.name`,a.name,{ph:'For example: Interview recruiting plan'}))}${fld('Instructions',eArea(`act.${a.id}.instr`,a.instr,{ph:'1. What to make\n2. What to include\n3. How it will be graded',h:96}))}`)}
  ${section(2,'Materials','Templates and examples learners can download.',`${a.materials.map((m,i)=>`<div class="filerow">${ic('file',18,'pencil')}<span class="col gap2 grow"><span class="m med">${esc(m.name)}</span><span class="c faded">${m.size}</span></span><button class="faded" data-act="amatdel" data-a="${a.id}" data-i="${i}" aria-label="Remove ${esc(m.name)}">${ic('trash',16)}</button></div>`).join('')}<button class="dropzone" data-act="amatadd" data-a="${a.id}">${ic('upload',16)} Drop files or <span class="link">browse</span> <span class="faded">· up to 50 MB</span></button>`)}
  ${section(3,'Submission','How and when learners hand in their work.',`<div class="field"><span class="label">Learners submit</span>${eSeg(`act.${a.id}.submit`,a.submit,[['file','A file'],['link','A link'],['text','Text']])}</div>
   <div class="row gap16" style="align-items:flex-start">${fld('Due date',eIn(`act.${a.id}.due`,a.due,{icon:'cal',ph:'Pick a date'}))}${fld('Time',eIn(`act.${a.id}.time`,a.time,{icon:'clock'}))}</div>
   ${eTog(`act.${a.id}.late`,a.late,'Accept late submissions',a.late?'Late work is marked as late. Learners see “You can still submit”.':'After the due date learners can’t submit.')}
   ${eTog(`act.${a.id}.remind`,a.remind,'Reminder email',a.remind?'The evening before the due date at 19:00, only to learners who haven’t submitted. Each learner can turn it off for this assignment.':'No reminder. Learners see the due date on the assignment and in This week.')}`)}
  ${section(4,'Review','What happens after a learner submits.',`<div class="row gap12" style="align-items:flex-start">${fld('Grade',eSel(`act.${a.id}.grade`,a.grade,['Out of 10','Out of 100','Pass / fail']))}${fld('Reviewers',eSel(`act.${a.id}.reviewers`,a.reviewers,['Course reviewers · 3','Only me','Teacher of the lesson']))}${fld('Review within',eSel(`act.${a.id}.within`,a.within,['24 hours','48 hours','72 hours']),{hint:'<span>After this a submission becomes overdue</span>'})}</div>${sideNote('Reviewers answer in 2 parts: What works · What to fix. Learners get an email when the review is sent.')}`)}
 </div><div class="ed-side">
  <section class="card pad col gap10"><div class="row gap8 s pencil">${ic('eye',16)}What learners see</div><span class="h3" data-show="act.${a.id}.name" data-empty="Untitled assignment">${esc(a.name||'Untitled assignment')}</span><span class="row gap6 c faded">${ic('cal',14)}<span>Due ${esc(a.dueShort||a.due||'—')}${a.due?', 23:59':''}</span></span><span class="s pencil" style="white-space:pre-line">${esc((a.instr||'Instructions show here').split('\n').map(cutLine).join('\n'))}</span><span><span class="btn btn-primary">Submit</span></span></section>
  ${S?`<section class="card pad col gap10"><h3 class="h3">Submissions</h3>${[['Submitted',`${S.submitted} of ${S.of}`],['On time',S.ontime],['Late',S.late]].map(([k,v])=>`<div class="row between s"><span class="pencil">${k}</span><span class="semi">${v}</span></div>`).join('')}<span class="badge ${S.tone}" style="align-self:flex-start">${S.status}</span><button class="link" data-act="msgq" data-tab="${S.tone==='b-over'?'overdue':'needs'}">Open in review queue ${ic('arrow',14)}</button></section>`:sideNote('Submissions show here after you publish.')}
 </div></div>`;}
ACT.amatadd=(el)=>{const a=ACTS[el.dataset.a];const names=['example-submission.pdf','grading-checklist.pdf','brief-template.docx'];a.materials.push({name:names[a.materials.length%3],size:'96 KB'});edSaving();render();};
ACT.amatdel=(el)=>{const a=ACTS[el.dataset.a],i=+el.dataset.i;const [x]=a.materials.splice(i,1);edSaving();render();toast(`${x.name} removed`,'Undo',()=>{a.materials.splice(i,0,x);render();});};

/* ---------- Library: every activity, rows open its editor ---------- */
st.libTab='all';st.libQ='';
function usedIn(a){const ls=[a.lesson].concat(a.alsoIn||[]).filter(Boolean).map(lessonById);if(!ls.length)return 'Not used yet';const cs=[...new Set(ls.map(l=>l.course))];return ls.length===1?`1 lesson · Module ${ls[0].mod+1}`:`${plural(ls.length,'lesson')} · ${cs.length} course${cs.length>1?'s':''}`;}
VIEWS['admin:library']=()=>{const all=Object.values(ACTS).filter(a=>!a.deleted);const q=st.libQ.toLowerCase();const list=all.filter(a=>(st.libTab==='all'||a.type===st.libTab)&&(!q||a.title.toLowerCase().includes(q)));
 const COLS=[['Activity',0],['Type',120],['Used in',170],['Size',140],['Updated',92,'c-last'],['Status',112]];const cell=(i,inner)=>`<div class="td ${COLS[i][1]?'':'grow'} ${COLS[i][2]||''}" ${COLS[i][1]?`style="width:${COLS[i][1]}px"`:''}>${inner}</div>`;
 return `<div class="page" style="max-width:none"><div class="row gap12"><div class="col gap4 grow"><h1 class="h1">Library</h1><p class="m pencil" style="margin:0">Reusable activities. Create them inside a lesson, reuse them here in any course.</p></div>${btn('New activity','secondary','data-act="notyet" data-msg="New activities are created inside a lesson: Courses → Curriculum → Add activity"','plus')}</div>
  <div class="tabs">${[['all','All'],['quiz','Quizzes'],['tf','True/False'],['gaps','Fill the gaps'],['assignment','Assignments']].map(([v,l])=>`<button class="tab ${st.libTab===v?'on':''}" data-act="libtab" data-v="${v}">${l}<span class="count">${v==='all'?all.length:all.filter(a=>a.type===v).length}</span></button>`).join('')}</div>
  <label class="search" style="width:280px">${ic('search',16)}<input data-libq placeholder="Search activities" value="${esc(st.libQ)}"></label>
  <div class="tbl"><div class="tr head">${COLS.map(([k],i)=>cell(i,`<span class="o faded">${k}</span>`)).join('')}</div>
  ${list.map(a=>`<div class="tr" data-act="nav" data-to="admin/activity/${a.id}">${cell(0,`<span class="typeicon sm">${ic(ACT_ICON[a.type],16)}</span><span class="col gap2" style="min-width:0"><span class="m med trunc">${esc(a.title)}</span><span class="c faded trunc">${esc(CED[a.course].title)}</span></span>`)}${cell(1,`<span class="badge b-neutral">${ACT_TYPE[a.type]}</span>`)}${cell(2,`<span class="s">${usedIn(a)}</span>`)}${cell(3,`<span class="s pencil">${actSize(a)}</span>`)}${cell(4,`<span class="s">${a.updated}</span>`)}${cell(5,stBadge(a.status))}</div>`).join('')||'<div class="empty"><span class="h3">No activities match</span></div>'}
  <div class="tfoot"><span class="s pencil">1–${list.length} of ${list.length}</span></div></div></div>`;};
ACT.libtab=(el)=>{st.libTab=el.dataset.v;render();};
document.addEventListener('input',e=>{if(e.target.dataset&&e.target.dataset.libq!==undefined){st.libQ=e.target.value;render();const i=document.querySelector('[data-libq]');if(i){i.focus();i.setSelectionRange(i.value.length,i.value.length);}}});

VIEWS['admin:lessons']=VIEWS['admin:interactive']=VIEWS['admin:library'];
/* Preview lines in “What learners see”: cut at the first clause mark (: , +) or at a word, never mid-word (06.10) */
function cutLine(x){if(x.length<=40)return x;const m=x.slice(4).search(/:| \+|,/);if(m>0)return x.slice(0,m+4)+'…';const sp=x.lastIndexOf(' ',30);return x.slice(0,sp>0?sp:30)+'…';}
